// Extract story ID from chat message
const message = $input.first().json?.chatInput || $input.first().json?.message || '';
const storyId = message.trim().toUpperCase();

if (!storyId || !/^[A-Z]+-\d+$/.test(storyId)) {
  throw new Error(`Invalid JIRA Story ID: '${storyId}'. Expected format: PROJECT-123`);
}

return [{ json: { story_id: storyId } }];

// Parse JIRA story response
const issue = $input.first().json;

const fields = issue.fields || {};

// Extract description text from Atlassian Document Format (ADF)
function extractText(adf) {
  if (!adf) return '';
  if (typeof adf === 'string') return adf;
  let text = '';
  if (adf.text) text += adf.text;
  if (adf.content && Array.isArray(adf.content)) {
    for (const node of adf.content) {
      text += extractText(node);
      if (['paragraph','heading','listItem','bulletList','orderedList'].includes(node.type)) {
        text += '\n';
      }
    }
  }
  return text;
}

// Extract acceptance criteria from description or custom field
const description = extractText(fields.description);

// Try to find acceptance criteria section
let acceptanceCriteria = '';
const acMatch = description.match(/acceptance criteria[:\s]+([\s\S]*?)(?=\n#|$)/i);
if (acMatch) {
  acceptanceCriteria = acMatch[1].trim();
}

// Try custom field for acceptance criteria (common field IDs)
const customFields = ['customfield_10016', 'customfield_10014', 'customfield_10300'];
for (const cf of customFields) {
  if (fields[cf]) {
    const cfText = extractText(fields[cf]);
    if (cfText) { acceptanceCriteria = cfText; break; }
  }
}

return [{
  json: {
    story_id: issue.key,
    issue_id: issue.id,
    summary: fields.summary || '',
    description: description,
    acceptance_criteria: acceptanceCriteria,
    issue_type: fields.issuetype?.name || '',
    status: fields.status?.name || '',
    priority: fields.priority?.name || ''
  }
}];

// Filter test cases linked to the story
const zephyrResponse = $input.first().json;
const storyData = $('Parse JIRA Story').first().json;

const testCases = zephyrResponse.values || zephyrResponse.testCases || [];
const issueId = storyData.issue_id;
const storyKey = storyData.story_id;

const linkedTestCases = testCases.filter(tc => {
  const links = tc.linkedIssues || tc.issueLinks || [];
  return links.some(link => {
    const id = link.issueId || link.id || '';
    const key = link.issueKey || link.key || '';
    return String(id) === String(issueId) || key === storyKey;
  });
});

return [{
  json: {
    story_id: storyKey,
    issue_id: issueId,
    summary: storyData.summary,
    description: storyData.description,
    acceptance_criteria: storyData.acceptance_criteria,
    all_testcases_count: testCases.length,
    linked_testcases: linkedTestCases.map(tc => ({
      key: tc.key || tc.testCaseKey || '',
      name: tc.name || tc.title || '',
      objective: tc.objective || '',
      status: tc.status?.name || tc.statusName || '',
      steps: (tc.testScript?.stepByStepScript?.steps ||
              tc.steps || []).map(s => ({
        description: s.description || '',
        expectedResult: s.expectedResult || ''
      }))
    }))
  }
}];

// Parse Claude's coverage analysis response
const claudeResponse = $input.first().json;
const filterData = $('Filter Linked Test Cases').first().json;

let analysisText = claudeResponse.text ||
  claudeResponse.content?.[0]?.text ||
  claudeResponse.message?.content?.[0]?.text ||
  claudeResponse.output?.[0]?.text ||
  JSON.stringify(claudeResponse);

// Strip markdown code fences if present
analysisText = analysisText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

let analysis;
try {
  analysis = JSON.parse(analysisText);
} catch (e) {
  // Try to extract JSON from the text
  const jsonMatch = analysisText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Failed to parse Claude coverage analysis: ' + analysisText.slice(0, 500));
  }
}

return [{
  json: {
    ...filterData,
    coverage_summary: analysis.coverage_summary || {},
    missing_scenarios: analysis.missing_scenarios || []
  }
}];

