// Parse generated test cases from Claude
const claudeResponse = $input.first().json;
const coverageData = $('Parse Coverage Analysis').first().json;

let tcText = claudeResponse.text ||
  claudeResponse.content?.[0]?.text ||
  claudeResponse.message?.content?.[0]?.text ||
  claudeResponse.output?.[0]?.text ||
  JSON.stringify(claudeResponse);

// Strip markdown code fences
tcText = tcText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

let newTestCases;
try {
  newTestCases = JSON.parse(tcText);
} catch (e) {
  const jsonMatch = tcText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    newTestCases = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Failed to parse generated test cases: ' + tcText.slice(0, 500));
  }
}

if (!Array.isArray(newTestCases)) {
  newTestCases = [newTestCases];
}

// Store coverage data in a static field for downstream nodes
const projectKey = coverageData.story_id.split('-')[0];

return newTestCases.map(tc => ({
  json: {
    testcase: tc,
    story_id: coverageData.story_id,
    issue_id: coverageData.issue_id,
    project_key: projectKey,
    coverage_summary: coverageData.coverage_summary,
    missing_scenarios: coverageData.missing_scenarios,
    linked_testcases: coverageData.linked_testcases,
    summary: coverageData.summary
  }
}));

