// Extract the created test case key from Zephyr response
const zephyrResponse = $input.first().json;
const inputData = $('Parse New Test Cases').first().json;

const testcaseKey = zephyrResponse.key ||
  zephyrResponse.testCaseKey ||
  zephyrResponse.id ||
  zephyrResponse.testCase?.key;

if (!testcaseKey) {
  throw new Error('Could not extract testcase key from Zephyr response: ' + JSON.stringify(zephyrResponse).slice(0, 300));
}

return [{
  json: {
    testcase_key: testcaseKey,
    testcase_name: inputData.testcase?.name || '',
    issue_id: inputData.issue_id,
    story_id: inputData.story_id,
    project_key: inputData.project_key,
    coverage_summary: inputData.coverage_summary,
    missing_scenarios: inputData.missing_scenarios,
    linked_testcases: inputData.linked_testcases,
    summary: inputData.summary
  }
}];

// Aggregate all results for final output
const allItems = $input.all();

// Get stable data from the first item (all items share story context)
const firstItem = allItems[0]?.json || {};
const linked = $('Extract Test Case Key').all() || [];

const newTestCasesCreated = linked.map(item => ({
  key: item.json.testcase_key,
  name: item.json.testcase_name
}));

// Build final structured output
const finalOutput = {
  story: {
    id: firstItem.story_id || '',
    summary: firstItem.summary || ''
  },
  coverage_summary: firstItem.coverage_summary || {},
  existing_testcases: (firstItem.linked_testcases || []).map(tc => ({
    key: tc.key,
    name: tc.name,
    objective: tc.objective
  })),
  missing_scenarios: firstItem.missing_scenarios || [],
  new_testcases_created: newTestCasesCreated
};

return [{ json: finalOutput }];
